package com.mycompany.ecoactionchat.server;
import java.net.*;import java.io.*;
public class ClientHandler implements Runnable {
 final ChatServer s;final Socket socket;PrintWriter out;String nick;ClientHandler(ChatServer s,Socket x){this.s=s;socket=x;}String name(){return nick;}void send(String m){if(out!=null)out.println(m);}
 public void run(){try(BufferedReader in=new BufferedReader(new InputStreamReader(socket.getInputStream()))){out=new PrintWriter(socket.getOutputStream(),true);String j=in.readLine();if(j==null||!j.startsWith("JOIN|"))return;nick=j.substring(5).trim();if(nick.isBlank()||!s.register(nick)){send("ERROR|Nickname blank or already in use.");return;}s.add(this);send("INFO|Connected.");for(String t:s.tasks)send("TASK|"+t);for(String r:s.reports)send("COLLECTION|"+r);s.broadcast("CHAT|Server|"+nick+" joined.");s.broadcast("USERLIST|"+s.userList());String l;while((l=in.readLine())!=null){if(l.equals("EXIT"))break;if(l.startsWith("CHAT|")){String m=l.substring(5).trim();if(!m.isBlank())s.broadcast("CHAT|"+nick+"|"+m);}else if(l.startsWith("TASK|"))s.task(l.substring(5));else if(l.startsWith("COLLECTION|"))s.report(l.substring(11));else if(l.startsWith("DONE|"))s.broadcast("TASK|"+l.substring(5));else if(l.startsWith("RENAME|")){String n=l.substring(7).trim();if(!n.isBlank()&&s.register(n)){String old=nick;nick=n;s.release(old);s.broadcast("CHAT|Server|"+old+" renamed to "+n);s.broadcast("USERLIST|"+s.userList());}else send("ERROR|Nickname invalid or already active.");}}}catch(IOException ignored){}finally{s.remove(this,nick);try{socket.close();}catch(IOException ignored){}}}
}